CREATE TABLE jobs (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, source TEXT NOT NULL, source_category TEXT NOT NULL, company TEXT NOT NULL, role TEXT NOT NULL, location_raw TEXT NOT NULL, original_apply_url TEXT NOT NULL, canonical_apply_url TEXT NOT NULL, simplify_url TEXT, ats_type TEXT NOT NULL, ats_job_id TEXT, tenant TEXT NOT NULL, source_age_days INTEGER, first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, approximate_posted_at TEXT, is_closed INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE applications (id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id), status TEXT NOT NULL CHECK(status IN ('DISCOVERED','QUEUED','PROCESSING','READY','NEEDS_REVIEW','SKIPPED','SUBMITTED')), stage TEXT NOT NULL, attention_reason TEXT, missing_fields TEXT NOT NULL DEFAULT '[]', attempt_count INTEGER NOT NULL DEFAULT 0, last_attempt_at TEXT, started_at TEXT, prepared_at TEXT, submitted_at TEXT, last_url TEXT, retryable INTEGER NOT NULL DEFAULT 0, screenshot_path TEXT, notes TEXT, session_available INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE runs (id TEXT PRIMARY KEY, started_at TEXT NOT NULL, finished_at TEXT, lookback_days INTEGER NOT NULL, discovered_count INTEGER NOT NULL DEFAULT 0, queued_count INTEGER NOT NULL DEFAULT 0, ready_count INTEGER NOT NULL DEFAULT 0, needs_review_count INTEGER NOT NULL DEFAULT 0, skipped_count INTEGER NOT NULL DEFAULT 0, submitted_count INTEGER NOT NULL DEFAULT 0, already_known_count INTEGER NOT NULL DEFAULT 0, error_count INTEGER NOT NULL DEFAULT 0, deferred_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE application_events (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id), run_id TEXT, timestamp TEXT NOT NULL, stage TEXT NOT NULL, event_type TEXT NOT NULL, message TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}');
CREATE TABLE application_attempts (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id), run_id TEXT, started_at TEXT NOT NULL, finished_at TEXT, last_heartbeat_at TEXT NOT NULL, outcome TEXT);
CREATE TABLE site_accounts (id TEXT PRIMARY KEY, tenant TEXT NOT NULL UNIQUE, email TEXT NOT NULL, credential_ref TEXT, created_at TEXT NOT NULL, verified_at TEXT, last_successful_login_at TEXT, notes TEXT);
CREATE TABLE answer_history (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id), normalized_question TEXT NOT NULL, original_question TEXT NOT NULL, answer TEXT NOT NULL, answer_source TEXT NOT NULL, generated INTEGER NOT NULL, fact_key TEXT, fact_revision INTEGER, created_at TEXT NOT NULL);
CREATE TABLE facts (id TEXT PRIMARY KEY, canonical_key TEXT NOT NULL, scope TEXT NOT NULL, value TEXT, value_type TEXT NOT NULL, source TEXT NOT NULL, stability TEXT NOT NULL, confidence REAL NOT NULL DEFAULT 1, first_confirmed_at TEXT NOT NULL, last_confirmed_at TEXT NOT NULL, expires_at TEXT, notes TEXT, used_count INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0, unknown INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(canonical_key,scope));
CREATE TABLE fact_history (id TEXT PRIMARY KEY, fact_id TEXT NOT NULL REFERENCES facts(id), before TEXT, after TEXT, source TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE question_aliases (id TEXT PRIMARY KEY, normalized_question TEXT NOT NULL, canonical_fact_key TEXT NOT NULL, scope TEXT NOT NULL, ats TEXT, company TEXT, confidence REAL NOT NULL, source TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(normalized_question,scope));
CREATE TABLE unresolved_questions (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id), question TEXT NOT NULL, choices TEXT NOT NULL DEFAULT '[]', canonical_key TEXT, scope TEXT NOT NULL, reason TEXT NOT NULL, answer TEXT, resolved INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE job_identity_aliases (fingerprint TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id));
CREATE TABLE source_observations (observation_key TEXT PRIMARY KEY, company TEXT NOT NULL, role TEXT NOT NULL, category TEXT NOT NULL, is_closed INTEGER NOT NULL, last_seen_at TEXT NOT NULL);
CREATE INDEX event_app_idx ON application_events(application_id);
CREATE INDEX queue_idx ON applications(status);
